LANGS = ["fr","pt","es","ar","sw"]
L = {l:{} for l in LANGS}
for en, tr in T.items():
    assert len(tr)==5, en
    for l,v in zip(LANGS,tr): L[l][en]=v
NOTE = {"pt":"Tradução provisória, a rever por falantes nativos.","es":"Traducción provisional, pendiente de revisión por hablantes nativos.","ar":"ترجمة أولية بانتظار مراجعة ناطقين أصليين.","sw":"Tafsiri ya awali, inasubiri mapitio ya wazungumzaji asilia.","fr":""}
js = "(function(){var L=%s,NOTE=%s,lang='en',rec=new WeakMap(),pend=false;\n" % (json.dumps(L,ensure_ascii=False), json.dumps(NOTE,ensure_ascii=False))
js += r"""function tr(s){var D=L[lang];if(!D)return s;var m=s.match(/^(\s*)([\s\S]*?)(\s*)$/),c=m[2];if(!c)return s;if(Object.prototype.hasOwnProperty.call(D,c))return m[1]+D[c]+m[3];return s;}
function visit(n){var v=n.nodeValue,r=rec.get(n),t;if(r&&v===r.t){t=(lang!=='en')?tr(r.o):r.o;if(t!==v){n.nodeValue=t;r.t=t;}return;}t=(lang!=='en')?tr(v):v;rec.set(n,{o:v,t:t});if(t!==v)n.nodeValue=t;}
function walk(){pend=false;if(!document.body)return;var w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,null),n,l=[];while((n=w.nextNode())){var p=n.parentNode;if(!p||/^(SCRIPT|STYLE|TEXTAREA)$/.test(p.nodeName))continue;if(p.closest&&p.closest('.no-tr'))continue;l.push(n);}for(var i=0;i<l.length;i++)visit(l[i]);}
function sched(){if(!pend){pend=true;(window.requestAnimationFrame||setTimeout)(walk);}}
function setLang(l){lang=(l==='en'||L[l])?l:'en';try{document.documentElement.lang=lang;document.documentElement.dir=(lang==='ar')?'rtl':'ltr';}catch(e){}var el=document.getElementById('lang-draft');if(el)el.textContent=NOTE[lang]||'';sched();}
new MutationObserver(sched).observe(document.documentElement,{childList:true,subtree:true,characterData:true});
if(window.jQuery){jQuery(document).on('shiny:inputchanged',function(e){if(e.name==='ui_lang')setLang(e.value);});jQuery(document).on('shiny:connected',function(){var c=jQuery('input[name=ui_lang]:checked').val();if(c)setLang(c);});}
})();"""
open("www/i18n.js","w",encoding="utf-8").write(js)
print(len(T),"chaines;",len(js),"octets")
